payload:
$ErrorActionPreference = 'Continue'
$target = 'fengie/mhw-mods'
$roots = @(
  'C:\Users\Xxkan\mhw-mods',
  'C:\Users\Xxkan\Documents\GitHub\mhw-mods',
  'C:\Users\Xxkan\source\repos\mhw-mods',
  'C:\Users\Xxkan\HeavenBridgeRepo'
)
$found = New-Object System.Collections.Generic.List[string]
foreach ($p in $roots) {
  if (Test-Path (Join-Path $p '.git')) { $found.Add((Resolve-Path $p).Path) }
}
try {
  Get-ChildItem -Path 'C:\Users\Xxkan' -Directory -Force -Recurse -Depth 4 -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -eq '.git' } |
    ForEach-Object {
      $rp = $_.Parent.FullName
      if (-not $found.Contains($rp)) { $found.Add($rp) }
    }
} catch {}

$result = @()
foreach ($repo in $found) {
  Push-Location $repo
  try {
    $origin = (git remote get-url origin 2>$null)
    if ($LASTEXITCODE -ne 0 -or $origin -notmatch 'fengie/mhw-mods') { continue }

    $fetch = (& git fetch --all --prune 2>&1 | Out-String).Trim()
    $current = (& git branch --show-current 2>$null | Out-String).Trim()
    $status = (& git status --porcelain=v1 2>$null | Out-String).Trim()
    $originMain = (& git rev-parse origin/main 2>$null | Out-String).Trim()
    $default = (& git symbolic-ref --short refs/remotes/origin/HEAD 2>$null | Out-String).Trim()
    $worktrees = (& git worktree list --porcelain 2>$null | Out-String).Trim()

    $branches = @()
    $localRefs = & git for-each-ref --format='%(refname:short)|%(objectname)|%(committerdate:iso8601)|%(authorname)|%(upstream:short)' refs/heads/
    foreach ($line in $localRefs) {
      if (-not $line) { continue }
      $parts = $line -split '\|',5
      $name = $parts[0]
      $sha = $parts[1]
      $date = $parts[2]
      $author = $parts[3]
      $upstream = $parts[4]
      $lr = (& git rev-list --left-right --count "origin/main...$name" 2>$null | Out-String).Trim()
      $anc = $false
      & git merge-base --is-ancestor $name origin/main 2>$null
      if ($LASTEXITCODE -eq 0) { $anc = $true }
      $treeEqual = $false
      & git diff --quiet "origin/main" $name 2>$null
      if ($LASTEXITCODE -eq 0) { $treeEqual = $true }
      $cherry = @(& git cherry origin/main $name 2>$null)
      $plus = @($cherry | Where-Object { $_ -like '+ *' }).Count
      $minus = @($cherry | Where-Object { $_ -like '- *' }).Count
      $commits = @(& git log --oneline --decorate=no -n 8 $name --not origin/main 2>$null)
      $branches += [ordered]@{
        scope='local'; name=$name; sha=$sha; date=$date; author=$author; upstream=$upstream;
        aheadBehind=$lr; ancestorOfMain=$anc; treeEqualMain=$treeEqual;
        cherryPlus=$plus; cherryMinus=$minus; uniqueCommitSample=$commits
      }
    }

    $remoteRefs = & git for-each-ref --format='%(refname:short)|%(objectname)|%(committerdate:iso8601)|%(authorname)' refs/remotes/origin/
    foreach ($line in $remoteRefs) {
      if (-not $line) { continue }
      $parts = $line -split '\|',4
      $name = $parts[0]
      if ($name -eq 'origin/HEAD') { continue }
      $short = $name -replace '^origin/',''
      $sha = $parts[1]
      $date = $parts[2]
      $author = $parts[3]
      $lr = (& git rev-list --left-right --count "origin/main...$name" 2>$null | Out-String).Trim()
      $anc = $false
      & git merge-base --is-ancestor $name origin/main 2>$null
      if ($LASTEXITCODE -eq 0) { $anc = $true }
      $treeEqual = $false
      & git diff --quiet "origin/main" $name 2>$null
      if ($LASTEXITCODE -eq 0) { $treeEqual = $true }
      $cherry = @(& git cherry origin/main $name 2>$null)
      $plus = @($cherry | Where-Object { $_ -like '+ *' }).Count
      $minus = @($cherry | Where-Object { $_ -like '- *' }).Count
      $commits = @(& git log --oneline --decorate=no -n 8 $name --not origin/main 2>$null)
      $branches += [ordered]@{
        scope='remote'; name=$short; fullRef=$name; sha=$sha; date=$date; author=$author;
        aheadBehind=$lr; ancestorOfMain=$anc; treeEqualMain=$treeEqual;
        cherryPlus=$plus; cherryMinus=$minus; uniqueCommitSample=$commits
      }
    }

    $result += [ordered]@{
      repo=$repo; origin=$origin; fetchOutput=$fetch; currentBranch=$current;
      dirty=([bool]$status); status=$status; originMain=$originMain; defaultRemote=$default;
      worktrees=$worktrees; branches=$branches
    }
  } finally { Pop-Location }
}
$result | ConvertTo-Json -Depth 8
